    public final boolean isMainCategory(@Nullable Category category) {
        if (category == null) {
            return false;
        }
        for (Category main : MAIN_CATEGORIES) {
            if (main != category) continue;
            return true;
        }
        return false;
    }

    public final boolean isOtherCategory(@Nullable Category category) {
        if (category == null) {
            return false;
        }
        for (Category other : OTHER_CATEGORIES) {
            if (other != category) continue;
            return true;
        }
        return false;
    }

