    private final void renderMessenger(DrawContext graphics, RemoteGuiPanel panel, GuiShareRemoteState state, RemoteTheme theme, int paletteSlot, float alpha) {
        float t = panel.messengerT();
        if (t <= 0.01f) {
            return;
        }
        float a = t * alpha;
        MessengerClient client = MessengerClient.INSTANCE;
        if (!client.isRunning()) {
            client.start();
        }
        float px = 518.0f;
        float py = 102.0f;
        float pw = 158.0f;
        float ph = 290.0f;
        float drawY = py + (1.0f - t) * 4.0f;
        float radius = this.remoteEffectiveCornerRadius(theme, 12.0f, pw, ph);
        this.drawThemeGlow(theme, px, drawY, pw, ph, radius, a);
        RemoteGuiPanelRenderer.drawThemeGlass$default(this, theme, paletteSlot, px, drawY, pw, ph, radius, a, 0.0f, 256, null);
        Render2D.outline(px, drawY, pw, ph, radius, 0.6f, this.color(255, 255, 255, 24, a));
        String owner = state.profileUsername;
        ArrayList<MessengerClient.Message> msgs = new ArrayList<MessengerClient.Message>();
        for (MessengerClient.Message message : client.snapshot()) {
            CharSequence charSequence = message.to();
            if (!(charSequence == null || StringsKt.isBlank((CharSequence)charSequence))) continue;
            msgs.add(message);
        }
        this.renderChatHeader(px, drawY, pw, radius, panel, state, client, theme, a);
        float listX = px + 7.0f;
        float listW = pw - 14.0f;
        float listTop = drawY + 22.0f;
        float listBottom = drawY + ph - 7.0f - 13.0f - 5.0f;
        float listH = listBottom - listTop;
        this.ensureChatWrap(listW, (List<MessengerClient.Message>)msgs);
        float contentH = 0.0f;
        float[] heights = new float[msgs.size()];
        int n = ((Collection)msgs).size();
        for (int i = 0; i < n; ++i) {
            Object e = msgs.get(i);
            Intrinsics.checkNotNullExpressionValue(e, (String)"get(...)");
            MessengerClient.Message message = (MessengerClient.Message)e;
            boolean bl = this.isChatGrouped((List<MessengerClient.Message>)msgs, i);
            Object e2 = msgs.get(i);
            Intrinsics.checkNotNullExpressionValue(e2, (String)"get(...)");
            heights[i] = this.chatBlockHeight(message, bl, this.isOwnerMessage((MessengerClient.Message)e2, owner));
            contentH += heights[i];
        }
        Render2D.pushScissor(graphics, px, listTop, pw, listH);
        float cursorY = this.snapPx(listBottom - contentH + panel.smoothMessengerScroll());
        int n2 = ((Collection)msgs).size();
        for (int i = 0; i < n2; ++i) {
            float blockH = heights[i];
            if (cursorY + blockH >= listTop - 20.0f && cursorY <= listBottom + 20.0f) {
                Object e = msgs.get(i);
                Intrinsics.checkNotNullExpressionValue(e, (String)"get(...)");
                MessengerClient.Message message = (MessengerClient.Message)e;
                boolean bl = this.isChatGrouped((List<MessengerClient.Message>)msgs, i);
                Object e3 = msgs.get(i);
                Intrinsics.checkNotNullExpressionValue(e3, (String)"get(...)");
                this.renderChatMessage(message, bl, this.isOwnerMessage((MessengerClient.Message)e3, owner), state, theme, listX, cursorY, listW, a);
            }
            cursorY += blockH;
        }
        if (msgs.isEmpty()) {
            String empty = client.isConnected() ? I18n.tr("Пока пусто...") : I18n.tr("Подключение...");
            float ew = Fonts.MEDIUM.width(empty, 6.0f);
            Fonts.MEDIUM.draw(empty, px + (pw - ew) * 0.5f, listTop + listH * 0.5f - 3.0f, 6.0f, this.color(255, 255, 255, 90, a));
        }
        Render2D.popScissor(graphics);
        this.renderChatInput(graphics, panel, theme, listX, drawY + ph - 7.0f - 13.0f, listW, 13.0f, a);
    }

