    private final boolean isChatGrouped(List<MessengerClient.Message> msgs, int index) {
        if (index <= 0) {
            return false;
        }
        MessengerClient.Message current = msgs.get(index);
        MessengerClient.Message previous = msgs.get(index - 1);
        return StringsKt.equals((String)current.user(), (String)previous.user(), (boolean)true) && current.ts() - previous.ts() <= 90000L;
    }

