    private final float chatBlockHeight(MessengerClient.Message message, boolean grouped, boolean mine) {
        List<String> lines = chatWrapCache.getOrDefault(message.id(), List.of(message.text()));
        float bubbleH = (float)lines.size() * 7.8f - 2.2f + 2.24f + 7.0f + this.chatQuoteExtra(message);
        float head = mine || grouped ? 0.0f : 14.0f;
        float edited = message.edited() ? 5.5f : 0.0f;
        return head + bubbleH + edited + 4.0f;
    }

    private final void renderChatMessage(MessengerClient.Message message, boolean grouped, boolean mine, GuiShareRemoteState state, RemoteTheme theme, float x, float y, float w, float a) {
        List<String> lines = chatWrapCache.getOrDefault(message.id(), List.of(message.text()));
        float textW = 0.0f;
        for (String line : lines) {
            textW = Math.max(textW, Fonts.MEDIUM.width(line, 5.6f));
        }
        float maxBubbleW = w * 0.86f;
        float quoteH = this.chatQuoteExtra(message);
        MessengerClient.Message quoted = message.replyTo() > 0L ? MessengerClient.INSTANCE.byId(message.replyTo()) : null;
        float contentW = textW;
        if (quoteH > 0.0f) {
            float qw = 4.4f + Math.max(Fonts.MEDIUM.width(this.chatQuoteName(quoted), 4.8f), Fonts.MEDIUM.width(this.chatQuoteText(quoted), 4.8f));
            contentW = Math.max(contentW, Math.min(qw, maxBubbleW - 9.0f));
        }
        float bubbleW = Math.min(maxBubbleW, contentW + 9.0f);
        float bubbleH = (float)lines.size() * 7.8f - 2.2f + 2.24f + 7.0f + quoteH;
        String time = CHAT_TIME_FMT.format(Instant.ofEpochMilli(message.ts()).atZone(ZoneId.systemDefault()));
        if (mine) {
            float bx = x + w - bubbleW;
            Render2D.rect(bx, y, bubbleW, bubbleH, 4.0f, theme.accentSoft(105.0f * a));
            if (quoteH > 0.0f) {
                this.drawChatQuote(quoted, theme, bx + 4.5f, y + 3.5f, bubbleW - 9.0f, a, true);
            }
            this.drawChatLines(lines, bx + 4.5f, y + 3.5f + quoteH, this.color(255, 255, 255, 235, a));
            float tw = Fonts.MEDIUM.width(time, 4.6f);
            Fonts.MEDIUM.draw(time, bx - tw - 3.0f, y + bubbleH - 4.6f - 1.5f, 4.6f, this.color(255, 255, 255, 97, a));
            if (message.edited()) {
                this.drawChatEditedMark(bx + bubbleW, y + bubbleH + 1.0f, a, true);
            }
            return;
        }
        float bubbleX = x + 11.0f + 4.0f;
        float bubbleY = y;
        if (!grouped) {
            this.drawChatAvatar(message, state, theme, x, y, a);
            Fonts.MEDIUM.draw(message.user(), bubbleX, y + 1.5f, 5.6f, this.color(255, 255, 255, 217, a));
            float nickW = Fonts.MEDIUM.width(message.user(), 5.6f);
            Fonts.MEDIUM.draw(time, bubbleX + nickW + 4.0f, y + 2.6f, 4.6f, this.color(255, 255, 255, 97, a));
            bubbleY = y + 11.0f + 3.0f;
        }
        bubbleW = Math.min(x + w - bubbleX, bubbleW);
        Render2D.rect(bubbleX, bubbleY, bubbleW, bubbleH, 4.0f, this.color(0, 0, 0, 40, a));
        Render2D.outline(bubbleX, bubbleY, bubbleW, bubbleH, 4.0f, 0.6f, this.color(255, 255, 255, 20, a));
        if (quoteH > 0.0f) {
            this.drawChatQuote(quoted, theme, bubbleX + 4.5f, bubbleY + 3.5f, bubbleW - 9.0f, a, false);
        }
        this.drawChatLines(lines, bubbleX + 4.5f, bubbleY + 3.5f + quoteH, this.color(255, 255, 255, 224, a));
        if (grouped) {
            float tw = Fonts.MEDIUM.width(time, 4.6f);
            Fonts.MEDIUM.draw(time, bubbleX + bubbleW + 3.0f, bubbleY + bubbleH - 4.6f - 1.5f, 4.6f, this.color(255, 255, 255, 77, a));
        }
        if (message.edited()) {
            this.drawChatEditedMark(bubbleX + 1.0f, bubbleY + bubbleH + 1.0f, a, false);
        }
    }

