    private final String clipChat(String text, float size, float maxW) {
        int cut;
        CharSequence charSequence = text;
        if (charSequence == null || charSequence.length() == 0 || maxW <= 0.0f) {
            return "";
        }
        if (Fonts.MEDIUM.width(text, size) <= maxW) {
            return text;
        }
        for (cut = text.length(); cut > 1; --cut) {
            String string = text.substring(0, cut);
            Intrinsics.checkNotNullExpressionValue((Object)string, (String)"substring(...)");
            if (!(Fonts.MEDIUM.width(string + "…", size) > maxW)) break;
        }
        String string = text.substring(0, cut);
        Intrinsics.checkNotNullExpressionValue((Object)string, (String)"substring(...)");
        return string + "…";
    }

    private final void ensureChatWrap(float listW, List<MessengerClient.Message> msgs) {
        float wrapW = listW * 0.86f - 9.0f;
        for (MessengerClient.Message message : msgs) {
            String text = message.text();
            if (chatWrapCache.containsKey(message.id()) && Intrinsics.areEqual((Object)text, (Object)chatWrapText.get(message.id()))) continue;
            ((Map)chatWrapCache).put(message.id(), this.wrapChat(text, wrapW));
            ((Map)chatWrapText).put(message.id(), text);
        }
        if (chatWrapCache.size() > msgs.size() + 64) {
            HashSet<Long> alive = new HashSet<Long>();
            for (MessengerClient.Message message : msgs) {
                alive.add(message.id());
            }
            chatWrapCache.keySet().retainAll((Collection)alive);
            chatWrapText.keySet().retainAll((Collection)alive);
        }
    }

    private final List<String> wrapChat(String text, float maxW) {
        ArrayList<String> lines = new ArrayList<String>();
        StringBuilder line = new StringBuilder();
        for (String word : text.split(" ")) {
            while (Fonts.MEDIUM.width(word, 5.6f) > maxW && word.length() > 1) {
                int cut;
                for (cut = word.length() - 1; cut > 1; --cut) {
                    String string = word.substring(0, cut);
                    if (!(Fonts.MEDIUM.width(string, 5.6f) > maxW)) break;
                }
                String head = word.substring(0, cut);
                if (line.length() > 0) {
                    lines.add(line.toString());
                    line = new StringBuilder();
                }
                lines.add(head);
                word = word.substring(cut);
            }
            String candidate = line.length() == 0 ? word : line + " " + word;
            if (Fonts.MEDIUM.width(candidate, 5.6f) > maxW && line.length() > 0) {
                lines.add(line.toString());
                line = new StringBuilder(word);
                continue;
            }
            line = new StringBuilder(candidate);
        }
        if (line.length() > 0) {
            lines.add(line.toString());
        }
        if (lines.isEmpty()) {
            lines.add("");
        }
        return lines;
    }

