    private final void renderConfigs(DrawContext graphics, float x, float y, RemoteGuiPanel panel, GuiShareRemoteState state, RemoteTheme theme, int paletteSlot, float alpha) {
        List<GuiShareConfigRow> rows = state.configs;
        float listX = x + 117.0f;
        float listW = 308.0f;
        float areaY = y + 5.0f + 30.0f;
        float areaH = 250.0f;
        if (rows.isEmpty()) {
            String msg = I18n.tr("Конфигов пока что нету");
            float size = 6.5f;
            float mw = Fonts.MEDIUM.width(msg, size);
            Fonts.MEDIUM.draw(msg, listX + (listW - mw) * 0.5f, areaY + areaH * 0.5f - 3.0f, size, this.rgba(255, 255, 255, 105.0f * alpha));
            return;
        }
        float contentH = 0.0f;
        int mw = this.getCFG_SECTION_TITLES().length;
        for (int kind = 0; kind < mw; ++kind) {
            int count = this.configRowCount(rows, kind);
            if (count == 0) continue;
            if (contentH > 0.0f) {
                contentH += 8.0f;
            }
            contentH += 13.0f + (float)count * 38.0f - 4.0f;
        }
        contentH = Math.max(0.0f, contentH);
        float viewH = areaH - 4.0f;
        float maxScroll = Math.max(0.0f, contentH - viewH);
        float scroll = this.clamp(panel.smoothConfigsScroll(), 0.0f, maxScroll);
        float slideOff = (1.0f - panel.categoryT()) * 8.0f;
        Render2D.pushScissor(graphics, listX, areaY - 4.0f, listW, areaH + 4.0f);
        RoundedScissor.push(graphics, listX, areaY - 4.0f, listW - 4.0f, areaH + 4.0f, 0.0f, 0.0f, 5.0f, 0.0f);
        boolean cardBlurJob = RemoteGuiWorld.beginCardBlurJob(graphics, listX, areaY - 4.0f, listW, areaH + 4.0f);
        float mouseX = x + panel.smoothMouseX();
        float mouseY = y + panel.smoothMouseY() - 22.0f;
        boolean mouseInList = state.open && mouseX >= listX && mouseX <= listX + listW && mouseY >= areaY && mouseY <= areaY + areaH;
        float cursor = areaY + 2.0f - scroll + slideOff;
        boolean anySection = false;
        int cardIndex = 0;
        int n = this.getCFG_SECTION_TITLES().length;
        for (int kind = 0; kind < n; ++kind) {
            if (this.configRowCount(rows, kind) == 0) continue;
            if (anySection) {
                cursor += 8.0f;
            }
            anySection = true;
            if (cursor + 13.0f >= areaY - 6.0f && cursor <= areaY + areaH + 6.0f) {
                this.drawConfigSection(this.getCFG_SECTION_TITLES()[kind], listX + 4.0f + 2.0f, cursor, alpha);
            }
            cursor += 13.0f;
            for (GuiShareConfigRow row : rows) {
                float appear;
                if (row.kind != kind) continue;
                float cx = listX + 4.0f;
                float cw = listW - 8.0f;
                float cy = cursor;
                cursor += 38.0f;
                if (cy + 34.0f < areaY - 6.0f || cy > areaY + areaH + 6.0f) continue;
                if ((appear = panel.rowAppear(cardIndex++)) < 0.001f) continue;
                float settleT = this.appearSettle(appear);
                float presence = settleT * settleT;
                float blurPhase = this.appearBlurPhase(appear);
                float drawY = cy + (1.0f - settleT) * 6.0f;
                boolean cardAppearing = appear < 0.999f;
                float blurTop = Math.max(drawY, areaY);
                float blurBottom = Math.min(drawY + 34.0f, areaY + areaH);
                boolean compositeCard = cardAppearing && cardBlurJob && blurBottom - blurTop > 0.5f && RemoteGuiWorld.recordCardBlurRect(cx, blurTop, cw, blurBottom - blurTop, presence, blurPhase);
                float ma = alpha;
                if (cardAppearing) {
                    if (!compositeCard) {
                        ma *= presence;
                    }
                    float cardScale = 0.85f + 0.15f * settleT;
                    float ox = cx + cw * 0.5f;
                    float oy = drawY + 17.0f;
                    graphics.getMatrices().pushMatrix();
                    graphics.getMatrices().translate(ox, oy);
                    graphics.getMatrices().scale(cardScale, cardScale);
                    graphics.getMatrices().translate(-ox, -oy);
                }
                float hoverT = mouseInList && mouseX >= cx && mouseX <= cx + cw && mouseY >= drawY && mouseY <= drawY + 34.0f ? 1.0f : 0.0f;
                this.renderConfigCard(theme, paletteSlot, state, row, cx, drawY, cw, ma, areaY + areaH, hoverT);
                if (!cardAppearing) continue;
                graphics.getMatrices().popMatrix();
            }
            cursor -= 4.0f;
        }
        panel.markAppearFrameDone();
        RoundedScissor.pop();
        Render2D.popScissor(graphics);
        if (cardBlurJob) {
            RemoteGuiWorld.endCardBlurJob(graphics);
        }
        if (maxScroll > 0.5f) {
            float trackX = x + 430.0f - 7.5f;
            float effR = this.remoteEffectiveCornerRadius(theme, 12.0f, listW, 280.0f);
            float botExtra = Math.max(0.0f, RenderHelper.cornerEdgeInset(effR, 1.0f) + 1.5f - 3.0f);
            float trackY = areaY + 3.0f;
            float trackH = areaH - 6.0f - botExtra;
            float thumbH = Math.max(12.0f, trackH * (viewH / contentH));
            float travel = Math.max(1.0f, trackH - thumbH);
            float thumbY = trackY + travel * (scroll / maxScroll);
            Render2D.rect(trackX, trackY, 1.5f, trackH, 0.75f, this.rgba(255, 255, 255, 20.0f * alpha));
            this.remoteFillVertical(theme, trackX, thumbY, 1.5f, thumbH, 0.75f, 160.0f * alpha);
        }
    }

    private final int configRowCount(List<GuiShareConfigRow> rows, int kind) {
        int count = 0;
        for (GuiShareConfigRow row : rows) {
            if (row.kind != kind) continue;
            ++count;
        }
        return count;
    }

    private final float appearSettle(float progress) {
        return CardAppear.Companion.settle(progress);
    }

    private final float appearBlurPhase(float progress) {
        return CardAppear.Companion.blurPhase(progress);
    }

    private final void drawConfigSection(String title, float x, float y, float alpha) {
        float size = 5.5f;
        Fonts.MEDIUM.draw(title, x, y + (13.0f - size) * 0.5f, size, this.rgba(255, 255, 255, 115.0f * alpha));
    }

    private final void renderConfigCard(RemoteTheme theme, int paletteSlot, GuiShareRemoteState state, GuiShareConfigRow row, float cx, float cy, float cw, float alpha, float bottomLimit, float hoverT) {
        float radius;
        float rbr = radius = 6.0f;
        if (cy + 34.0f > bottomLimit - 16.0f) {
            float t = this.clamp((cy + 34.0f - (bottomLimit - 16.0f)) / 16.0f, 0.0f, 1.0f);
            rbr = radius + (12.0f - radius) * t;
        }
        boolean readOnly = row.readOnly();
        float tint = row.active ? 1.0f : (row.premium() ? 0.5f : 0.0f);
        this.drawGlassCardRemote(theme, paletteSlot, cx, cy, cw, 34.0f, radius, radius, rbr, radius, alpha, Math.max(hoverT, tint * 0.65f));
        float overlayRadius = radius + 1.5f;
        float overlayRbr = rbr + 1.5f;
        int overlayTop = this.rgba(255, 255, 255, (7.0f + 5.0f * hoverT) * alpha);
        int overlayBottom = this.rgba(255, 255, 255, 1.5f * alpha);
        Render2D.rect(cx, cy, cw, 34.0f, overlayRadius, overlayRadius, overlayRbr, overlayRadius, overlayTop, overlayTop, overlayBottom, overlayBottom);
        if (tint > 0.01f) {
            int ga = theme.gradientA(22.0f * tint * alpha);
            int gb = theme.gradientB(22.0f * tint * alpha);
            Render2D.rect(cx, cy, cw, 34.0f, overlayRadius, overlayRadius, overlayRbr, overlayRadius, ga, gb, gb, ga);
        }
        int idleTop = this.rgba(255, 255, 255, (30.0f + 22.0f * hoverT) * alpha);
        int idleBottom = this.rgba(255, 255, 255, (10.0f + 8.0f * hoverT) * alpha);
        int outTop = ColorEngine.lerpColor(idleTop, theme.gradientA(78.0f * alpha), tint);
        int outBottom = ColorEngine.lerpColor(idleBottom, theme.gradientB(52.0f * alpha), tint);
        Render2D.outline(cx, cy, cw, 34.0f, overlayRadius, overlayRadius, overlayRbr, overlayRadius, 0.6f, outTop, outTop, outBottom, outBottom);
        float avatarX = cx + 8.0f;
        float avatarY = cy + 8.0f;
        this.renderConfigAvatar(state, row, avatarX, avatarY, alpha);
        float textX = avatarX + 18.0f + 7.0f;
        float nameY = cy + 7.5f;
        int nameColor = row.premium() ? theme.accentBright((235.0f + 20.0f * hoverT) * alpha) : this.rgba(255, 255, 255, (215.0f + 35.0f * hoverT) * alpha);
        float actionsW = readOnly ? 12.0f : 59.0f;
        float nameLimit = cx + cw - actionsW - textX - (row.cloud ? 15.0f : 0.0f);
        RenderHelper.drawScrollingText(row.name, textX, nameY, Math.max(10.0f, nameLimit), 7.0f, nameColor);
        float nameW = Math.min(Fonts.MEDIUM.width(row.name, 7.0f), Math.max(10.0f, nameLimit));
        if (row.cloud) {
            float badgeX = textX + nameW + 5.0f;
            float badgeY = nameY - 1.0f;
            this.remoteFillHorizontal(theme, badgeX, badgeY, 10.0f, 10.0f, 3.0f, 62.0f * alpha);
            float iconSize = 5.5f;
            float iconW = Fonts.KIMIKO.msdfWidth(CFG_ICON_CLOUD, iconSize);
            this.remoteMsdfIcon(theme, Fonts.KIMIKO, CFG_ICON_CLOUD, badgeX + (10.0f - iconW) * 0.5f, badgeY + (10.0f - iconSize) * 0.5f, iconSize, 225.0f * alpha, 0.5f);
        }
        float subLimit = Math.max(10.0f, cx + cw - actionsW - textX);
        RenderHelper.drawScrollingText(row.subtitle, textX, cy + 19.0f, subLimit, 5.5f, this.rgba(255, 255, 255, 108.0f * alpha));
        if (readOnly) {
            return;
        }
        float bx = cx + cw - 5.0f - 15.0f;
        float by = cy + 9.5f;
        int n = CFG_ACTION_ICONS.length + -1;
        if (0 <= n) {
            do {
                int i = n--;
                float boxAlpha = 20.0f * alpha * (0.5f + 0.5f * hoverT);
                Render2D.rect(bx, by, 15.0f, 15.0f, 3.5f, this.rgba(255, 255, 255, boxAlpha));
                String glyph = CFG_ACTION_ICONS[i];
                float size = CFG_ACTION_ICON_SIZE[i];
                float iw = Fonts.KIMIKO.msdfWidth(glyph, size);
                float gx = bx + (15.0f - iw) * 0.5f + CFG_ACTION_ICON_X[i];
                float gy = by + (15.0f - size) * 0.5f + CFG_ACTION_ICON_Y[i];
                if (i == 1 && row.cloud) {
                    this.remoteMsdfIcon(theme, Fonts.KIMIKO, glyph, gx, gy, size, 185.0f * alpha, 0.5f);
                } else {
                    Fonts.KIMIKO.msdf(glyph, gx, gy, size, this.rgba(255, 255, 255, 185.0f * alpha));
                }
                bx -= 17.0f;
            } while (0 <= n);
        }
    }

