    private final PopupLayout popupLayout(float x, float y, RemoteGuiPanel panel) {
        String moduleName = panel.popupDisplayed();
        if (StringsKt.isBlank((CharSequence)moduleName)) {
            return null;
        }
        float t = panel.popupT();
        if (t <= 0.01f) {
            return null;
        }
        List<GuiSharePopupRow> rows = panel.popupRows();
        List<Setting> widgets = CollectionsKt.emptyList();
        float pref = 0.0f;
        float contentH = 0.0f;
        if (!((Collection)rows).isEmpty()) {
            for (GuiSharePopupRow row : rows) {
                pref = Math.max(pref, this.popupRowPreferredWidth(row));
                contentH += this.popupRowHeight(row) + 4.0f;
            }
            contentH -= 4.0f;
        } else {
            Module module = this.findModule(moduleName);
            if (module == null) {
                return null;
            }
            Module module2 = module;
            widgets = this.popupWidgets(module2);
            if (widgets.isEmpty()) {
                return null;
            }
            int visibleCount = 0;
            for (Setting setting : widgets) {
                pref = Math.max(pref, setting.preferredWidth());
                if (!setting.isVisible()) continue;
                contentH += setting.height() + 4.0f;
                ++visibleCount;
            }
            if (visibleCount == 0) {
                return null;
            }
            contentH -= 4.0f;
        }
        float width = this.clamp(pref + 10.0f + 4.0f, 110.0f, 180.0f);
        float zoneH = 250.0f;
        float maxBodyH = zoneH - 7.0f - 7.0f - 8.0f;
        float bodyViewH = Math.min(contentH, maxBodyH);
        float height = 7.0f + bodyViewH + 7.0f;
        float px = x + panel.popupHoldX();
        float py = y + panel.popupHoldY() - 22.0f + (1.0f - t) * 4.0f;
        return new PopupLayout(rows, widgets, px, py, width, height, bodyViewH, contentH, t);
    }

    @JvmStatic
    @Nullable
    public static final float[] popupDrawRect(@NotNull RemoteGuiPanel panel) {
        Intrinsics.checkNotNullParameter((Object)panel, (String)"panel");
        float[] bindRect = INSTANCE.bindPopupDrawRect(panel);
        PopupLayout popupLayout = INSTANCE.popupLayout(80.0f, 102.0f, panel);
        if (popupLayout == null) {
            return bindRect;
        }
        PopupLayout layout = popupLayout;
        float left = layout.getPx();
        float top = layout.getPy();
        float right = left + layout.getWidth();
        float bottom = top + layout.getHeight();
        List<GuiSharePopupRow> rows = layout.getRows();
        if (!((Collection)rows).isEmpty()) {
            float rowX = layout.getPx() + 5.0f;
            float rowW = layout.getWidth() - 10.0f;
            float maxScroll = Math.max(0.0f, layout.getContentH() - layout.getBodyViewH());
            float scroll = INSTANCE.clamp(panel.smoothPopupScroll(), 0.0f, maxScroll);
            float overlayY = layout.getPy() + 7.0f - scroll;
            for (GuiSharePopupRow row : rows) {
                float[] rect;
                if (row.open && INSTANCE.hasOverlay(row) && (rect = INSTANCE.overlayRect(panel, row, rowX, overlayY, rowW)) != null) {
                    left = Math.min(left, rect[0]);
                    top = Math.min(top, rect[1]);
                    right = Math.max(right, rect[0] + rect[2]);
                    bottom = Math.max(bottom, rect[1] + rect[3]);
                }
                overlayY += INSTANCE.popupRowHeight(row) + 4.0f;
            }
        }
        float pad = Math.max(6.0f, panel.theme().glowRadius()) + 8.0f;
        float[] maxScroll = new float[]{left - pad, top - pad, right - left + pad * 2.0f, bottom - top + pad * 2.0f};
        float[] rect = maxScroll;
        if (bindRect == null) {
            return rect;
        }
        float mergedLeft = Math.min(rect[0], bindRect[0]);
        float mergedTop = Math.min(rect[1], bindRect[1]);
        float mergedRight = Math.max(rect[0] + rect[2], bindRect[0] + bindRect[2]);
        float mergedBottom = Math.max(rect[1] + rect[3], bindRect[1] + bindRect[3]);
        float[] fArray = new float[]{mergedLeft, mergedTop, mergedRight - mergedLeft, mergedBottom - mergedTop};
        return fArray;
    }

    private final float[] bindPopupDrawRect(RemoteGuiPanel panel) {
        GuiShareBindPopup bind = panel.state().bindPopup;
        if (!bind.visible) {
            return null;
        }
        float pad = Math.max(6.0f, panel.theme().glowRadius()) + 8.0f;
        float x = 80.0f + bind.x * 430.0f;
        float y = 102.0f + bind.y * 290.0f;
        float[] fArray = new float[]{x - pad, y - pad, 108.0f + pad * 2.0f, 61.0f + pad * 2.0f};
        return fArray;
    }

    private final float remoteOverlayY(RemoteGuiPanel panel, float rowY, float overlayH) {
        float below = rowY + 16.0f + 1.0f;
        float screenH = panel.state().screenHeight;
        if (screenH <= 1.0f) {
            return below;
        }
        float shift = screenH * 0.5f - 145.0f - 102.0f;
        float ownerRowY = rowY + shift;
        float ownerBelow = ownerRowY + 16.0f + 1.0f;
        float margin = 5.0f;
        if (ownerBelow + overlayH <= screenH - margin) {
            return ownerBelow - shift;
        }
        float ownerAbove = ownerRowY - overlayH - 1.0f;
        if (ownerAbove >= margin) {
            return ownerAbove - shift;
        }
        return Math.max(margin, screenH - margin - overlayH) - shift;
    }

    private final float listDropWidth(List<String> options, boolean scrollable) {
        float maxTextW = 0.0f;
        for (String option : options) {
            maxTextW = Math.max(maxTextW, Fonts.MEDIUM.width(option, 5.0f));
        }
        float base = maxTextW + 13.4f + 3.4f;
        return scrollable ? base + 5.0f : base;
    }

    private final float[] overlayRect(RemoteGuiPanel panel, GuiSharePopupRow row, float x, float y, float w) {
        float[] fArray;
        switch (row.type) {
            case "c": {
                float dropW = 82.0f;
                float dropH = 78.0f;
                float[] fArray2 = new float[]{x + w - dropW - 4.0f, this.remoteOverlayY(panel, y, dropH), dropW, dropH};
                fArray = fArray2;
                break;
            }
            case "m": 
            case "n": {
                List<String> options = row.options;
                if (options.isEmpty()) {
                    return null;
                }
                boolean single = Intrinsics.areEqual((Object)"m", (Object)row.type);
                boolean scrollable = single && options.size() > 6;
                float dropW = this.listDropWidth(options, scrollable);
                int visible = single ? Math.min(options.size(), 6) : options.size();
                float dropH = 1.7f + (float)visible * 13.3f;
                float[] fArray3 = new float[]{x + w - dropW - 4.0f, this.remoteOverlayY(panel, y, dropH), dropW, dropH};
                fArray = fArray3;
                break;
            }
            default: {
                fArray = null;
            }
        }
        return fArray;
    }

    private final void renderPopup(DrawContext graphics, float x, float y, RemoteGuiPanel panel, GuiShareRemoteState state, RemoteTheme theme, int paletteSlot, float alpha) {
        float rowW;
        float rowX;
        PopupLayout popupLayout = this.popupLayout(x, y, panel);
        if (popupLayout == null) {
            return;
        }
        PopupLayout layout = popupLayout;
        float pa = alpha * layout.getT();
        List<GuiSharePopupRow> rows = layout.getRows();
        List<Setting> widgets = layout.getWidgets();
        float contentH = layout.getContentH();
        float width = layout.getWidth();
        float bodyViewH = layout.getBodyViewH();
        float height = layout.getHeight();
        float px = layout.getPx();
        float py = layout.getPy();
        GuiLayerBlurRenderer.markPopupBoundary(graphics);
        this.drawThemeGlow(theme, px, py, width, height, 8.0f, pa);
        RemoteGuiPanelRenderer.drawThemeGlass$default(this, theme, paletteSlot, px, py, width, height, 8.0f, pa, 0.0f, 256, null);
        Render2D.outline(px, py, width, height, 8.0f, 0.6f, this.rgba(255, 255, 255, 24.0f * pa));
        float maxScroll = Math.max(0.0f, contentH - bodyViewH);
        float scroll = this.clamp(panel.smoothPopupScroll(), 0.0f, maxScroll);
        float bodyY = py + 7.0f;
        Render2D.pushScissor(graphics, px, bodyY, width, bodyViewH);
        float yy = bodyY - scroll;
        if (!((Collection)rows).isEmpty()) {
            rowX = px + 5.0f;
            rowW = width - 10.0f;
            for (GuiSharePopupRow row : rows) {
                float sh = this.popupRowHeight(row);
                if (yy + sh >= bodyY - 6.0f && yy <= bodyY + bodyViewH + 6.0f) {
                    this.renderPopupRow(theme, row, rowX, yy, rowW, pa);
                }
                yy += sh + 4.0f;
            }
        } else {
            for (Setting setting : widgets) {
                if (!setting.isVisible()) continue;
                float sh = setting.height();
                if (yy + sh >= bodyY - 6.0f && yy <= bodyY + bodyViewH + 6.0f) {
                    Fonts.MEDIUM.draw(I18n.tr(setting.name()), px + 5.0f + 6.0f, yy + 4.2f, 6.5f, this.rgba(255, 255, 255, 200.0f * pa));
                    float hintX = px + width - 5.0f - 4.0f - 19.1f - 6.0f;
                    Render2D.rect(hintX, yy + 6.0f, 30.0f, 4.0f, 2.0f, this.rgba(255, 255, 255, 26.0f * pa));
                    this.remoteFillHorizontal(theme, hintX, yy + 6.0f, 17.0f, 4.0f, 2.0f, 140.0f * pa);
                }
                yy += sh + 4.0f;
            }
        }
        Render2D.popScissor(graphics);
        if (contentH > bodyViewH + 0.5f) {
            float trackX = px + width - 4.5f;
            float thumbH = Math.max(12.0f, bodyViewH * (bodyViewH / contentH));
            float thumbY = bodyY + (bodyViewH - thumbH) * (scroll / maxScroll);
            Render2D.rect(trackX, bodyY, 1.5f, bodyViewH, 0.75f, this.rgba(255, 255, 255, 20.0f * pa));
            this.remoteFillVertical(theme, trackX, thumbY, 1.5f, thumbH, 0.75f, 160.0f * pa);
        }
        if (!((Collection)rows).isEmpty()) {
            rowX = px + 5.0f;
            rowW = width - 10.0f;
            float overlayY = bodyY - scroll;
            boolean boundaryEmitted = false;
            for (GuiSharePopupRow row : rows) {
                if (row.open && this.hasOverlay(row)) {
                    if (!boundaryEmitted) {
                        GuiLayerBlurRenderer.markPopupBoundary(graphics);
                        boundaryEmitted = true;
                    }
                    this.renderPopupOverlay(theme, paletteSlot, panel, row, rowX, overlayY, rowW, pa);
                }
                overlayY += this.popupRowHeight(row) + 4.0f;
            }
        }
    }

